        elif t == "min_words":
            n = len(words_all(b))
            if n < r["n"]:
                fails.append(f"too short: {n} words, at least {r['n']} wanted")
        elif t == "max_chars":
            n = len(b.strip())
            if n > r["n"]:
                fails.append(f"too long: {n} characters, the limit is {r['n']}")
        elif t == "min_chars":
